import{_ as a,o as n,a as i,b as e}from"./app.C41L12d5.js";const o="data:image/png;base64,",s="/ascendc.github.io/assets/conv3d_forward_diagram.OZfh6c8y.png",l="/ascendc.github.io/assets/conv3d_padding.BEtkCemD.png",p="/ascendc.github.io/assets/conv3d_stride.BXdjxW34.png",c="/ascendc.github.io/assets/conv3d_dilation.Ba85ucxq.png",b=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"卷积计算","link":"/api/SIMD-API/adv_api/convolution_compute/convolution_compute"},{"text":"Conv3D核函数（Kernel）侧接口","link":"/api/SIMD-API/adv_api/convolution_compute/Conv3D_Kernel/Conv3d_Kernel"},{"text":"Conv3D使用说明","link":"/api/SIMD-API/adv_api/convolution_compute/Conv3D_Kernel/Conv3D_usage"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/convolution_compute/Conv3D_Kernel/Conv3D_usage.md","filePath":"api/SIMD-API/adv_api/convolution_compute/Conv3D_Kernel/Conv3D_usage.md","outlineHeaders":[{"level":2,"title":"需要包含的头文件","slug":"需要包含的头文件","link":"#需要包含的头文件"}],"lastUpdated":1788515292000}'),d={name:"api/SIMD-API/adv_api/convolution_compute/Conv3D_Kernel/Conv3D_usage.md"};function h(v,t,r,g,C,A){return n(),i("div",null,[...t[0]||(t[0]=[e('<div><article class="markdown-body"><h1>Conv3D使用说明</h1><p>Ascend C提供一组Conv3D高阶API，方便用户快速实现3维卷积正向矩阵运算。3维正向卷积的示意图如<a href="#fig198021635102613">图1</a>，其计算公式为：</p><p><img src="'+o+'" alt></p><ul><li>X为Conv3D卷积的特征矩阵Input。</li><li>W为Conv3D卷积的权重矩阵Weight。</li><li>B为Conv3D卷积的偏置矩阵Bias。</li><li>Y为完成卷积及偏置操作之后的结果矩阵Output。</li></ul><p><strong>图1</strong> 3维正向卷积示意图<span id="fig198021635102613"></span><br><img src="'+s+'" alt title="3维正向卷积示意图"></p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>Cin为Input的输入通道大小Channel；Din为Input的Depth维度大小；Hin为Input的Height维度大小；Win为Input的Width维度大小；Cout为Weight、Output的输出通道大小；Dout为Output的Depth维度的大小；Hout为Output的Height维度大小；Wout为Output的Width维度大小；下文中提及的M维度，为卷积正向操作过程中的输入Input在img2col展开后的纵轴，数值上等于Hout * Wout。 Channel、Depth、Height、Width后续简称为C、D、H、W。</p></div><p>除上述基础运算外，在Conv3D计算中可以设置参数Padding、Stride和Dilation，具体含义如下。</p><ul><li>Padding代表在输入矩阵的三个维度上填充0，见<a href="#fig16852164019363">图2</a>。</li><li>Stride代表卷积核三个维度上滑动的距离，见<a href="#fig137769564018">图3</a>。</li><li>Dilation代表卷积核三个维度上每个数据的间距，见<a href="#fig1015315044111">图4</a>。</li></ul><p><strong>图2</strong> 卷积3D正向Padding示意图<span id="fig16852164019363"></span><br><img src="'+l+'" alt title="卷积3D正向Padding示意图"></p><p><strong>图3</strong> 卷积3D正向Stride示意图<span id="fig137769564018"></span><br><img src="'+p+'" alt title="卷积3D正向Stride示意图"></p><p><strong>图4</strong> 卷积3D正向Dilation示意图<span id="fig1015315044111"></span><br><img src="'+c+`" alt title="卷积3D正向Dilation示意图"></p><p>核函数（Kernel）侧实现Conv3D运算的步骤概括为：</p><ol><li>创建Conv3D对象。</li><li>初始化操作。</li><li>设置3D卷积输入Input、Weight、Bias和输出Output。</li><li>完成3D卷积操作。</li><li>结束3D卷积操作。</li></ol><p>使用Conv3D高阶API实现卷积正向的具体步骤如下：</p><ol><li><p>创建Conv3D对象。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>#include &quot;lib/conv/conv3d/conv3d_api.h&quot;

using inputType = ConvApi::ConvType&lt;AscendC::TPosition::GM, ConvFormat::NDC1HWC0, bfloat16_t&gt;;
using weightType = ConvApi::ConvType&lt;AscendC::TPosition::GM, ConvFormat::FRACTAL_Z_3D, bfloat16_t&gt;;
using outputType = ConvApi::ConvType&lt;AscendC::TPosition::GM, ConvFormat::NDC1HWC0, bfloat16_t&gt;;
using biasType = ConvApi::ConvType&lt;AscendC::TPosition::GM, ConvFormat::ND, float&gt;; // 可选参数

Conv3dApi::Conv3D&lt;inputType, weightType, outputType, biasType&gt; conv3dApi;
</code></pre></div><p>创建对象时需要传入Input、Weight和Output参数类型信息；Bias的参数类型为可选参数，不带Bias输入的卷积计算场景，不传入该参数。类型信息通过ConvType来定义，包括：内存逻辑位置、数据格式、数据类型。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>template &lt;TPosition POSITION, ConvFormat FORMAT, typename TYPE&gt;
struct ConvType {
    constexpr static TPosition pos = POSITION;   // Conv3d输入或输出在内存上的位置
    constexpr static ConvFormat format = FORMAT; // Conv3d输入或者输出的数据格式
    using T = TYPE;                              // Conv3d输入或输出的数据类型
};
</code></pre></div><p>下面简要介绍在创建对象时使用到的相关数据结构，开发者可选择性地了解这些内容。用于创建Conv3D对象的数据结构定义如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>template &lt;
    class INPUT_TYPE, class WEIGHT_TYPE, class OUTPUT_TYPE, class BIAS_TYPE = biasType, class CONV_CFG = Conv3dParam&gt;
using Conv3D =
    Conv3dIntfExt&lt;Config&lt;ConvApi::ConvDataType&lt;INPUT_TYPE, WEIGHT_TYPE, OUTPUT_TYPE, BIAS_TYPE, CONV_CFG&gt;&gt;, Impl, Intf&gt;
</code></pre></div><p>其中，Conv3dIntfExt和Conv3dParam数据结构定义如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>template &lt;
    class Conv3dCfg, template &lt;typename, class, bool&gt; class Impl = Conv3dApiImpl,
    template &lt;class, template &lt;typename, class, bool&gt; class&gt; class Intf = Conv3dIntf&gt;
struct Conv3dIntfExt : public Intf&lt;Conv3dCfg, Impl&gt; {
    __aicore__ inline Conv3dIntfExt() {}
};
struct Conv3dParam : public ConvApi::ConvParam {
    __aicore__ inline Conv3dParam(){};
};
</code></pre></div><p>这里的Conv3dIntf是Conv3dIntfExt的基类，Conv3dCfg是Conv3dIntf模板入参，数据结构定义如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>template &lt;class Config, template &lt;typename, class, bool&gt; class Impl&gt;
struct Conv3dIntf {
    using InputT = typename Config::SrcAT;
    using WeightT = typename Config::SrcBT;
    using OutputT = typename Config::DstT;
    using BiasT = typename Config::BiasT;
    using L0cT = typename Config::L0cT;
    using ConvParam = typename Config::ConvParam;
    __aicore__ inline Conv3dIntf() {}
} template &lt;class ConvDataType&gt;
struct Conv3dCfg : public ConvApi::ConvConfig&lt;ConvDataType&gt; {
public:
    __aicore__ inline Conv3dCfg() {}
    using ContextData = struct _ : public ConvApi::ConvConfig&lt;ConvDataType&gt;::ContextData {
        __aicore__ inline _() {}
    };
};
</code></pre></div><p><strong>表1</strong> ConvType说明</p><p><span id="table19081115275"></span></p><table><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td>TPosition</td><td>内存逻辑位置。<br> Input矩阵可设置为TPosition::GM。<br>Weight矩阵可设置为TPosition::GM。<br>Bias矩阵可设置为TPosition::GM。<br>Output矩阵可设置为TPosition::GM。</td></tr><tr><td>ConvFormat</td><td>数据格式。<br> Input矩阵可设置为ConvFormat::NDC1HWC0。<br>Weight矩阵可设置为ConvFormat::FRACTAL_Z_3D。<br>Bias矩阵可设置为ConvFormat::ND。<br>Output矩阵可设置为ConvFormat::NDC1HWC0。</td></tr><tr><td>TYPE</td><td>数据类型。<br>Input矩阵可设置为half、bfloat16_t。<br>Weight矩阵可设置为half、bfloat16_t。<br>Bias矩阵可设置为half、float。<br>Output矩阵可设置为half、bfloat16_t。<span data-filter="A3,910b"><br><br>注意：输入输出的矩阵数据类型需要对应，具体支持的数据类型组合关系请参考表2。</span></td></tr></tbody></table><div data-filter="A3,910b"><p><strong>表2</strong> Conv3D输入输出数据类型的组合说明</p><table><thead><tr><th>Input矩阵</th><th>Weight矩阵</th><th>Bias</th><th>Output矩阵</th><th>支持平台</th></tr></thead><tbody><tr data-filter="A3"><td>half</td><td>half</td><td>half</td><td>half</td><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td></tr><tr data-filter="A3"><td>bfloat16_t</td><td>bfloat16_t</td><td>float</td><td>bfloat16_t</td><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td></tr></tbody></table></div></li><li><p>初始化操作。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>Conv3dApi::Conv3D&lt;inputType, weightType, outputType, biasType&gt; conv3dApi;
TPipe pipe;                                                        // 初始化TPipe
conv3dApi.Init(&amp;tiling);                                           // 初始化conv3dApi
</code></pre></div></li><li><p>设置3D卷积的输入Input、Weight、Bias和输出Output。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>conv3dApi.SetWeight(weightGm);               // 设置当前核的输入weight在gm上的地址
if (biasFlag) {
    conv3dApi.SetBias(biasGm);               // 设置当前核的输入bias在gm上的地址
}
// 设置input各个维度在当前核的偏移
conv3dApi.SetInputStartPosition(diStartPos, mStartPos);
// 设置当前核的cout,dout,m大小
conv3dApi.SetSingleOutputShape(singleCoreCout, singleCoreDout, singleCoreM);

// 当前Conv3D仅支持单batch的卷积计算，多batch场景通过for循环实现，在循环间计算当前batch的地址偏移
for (uint64_t batchIter = 0; batchIter &lt; singleCoreBatch; ++batchIter) {
    conv3dApi.SetInput(inputGm[batchIter * inputOneBatchSize]);    // 设置当前核的输入input在gm上的地址
}
</code></pre></div></li><li><p>完成3D卷积操作。</p><p>调用<a href="IterateAll.html">IterateAll</a>完成单核上所有数据的计算。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>for (uint64_t batchIter = 0; batchIter &lt; singleCoreBatch; ++batchIter) {
    ...
    conv3dApi.IterateAll(outputGm[batchIter * outputOneBatchSize]);    // 调用IterateAll完成Conv3D计算
    ...
}
</code></pre></div></li><li><p>结束3D卷积操作。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>for (uint64_t batchIter = 0; batchIter &lt; singleCoreBatch; ++batchIter) {
    ...
    conv3dApi.End();    //清除EventID和释放内部申请的临时内存
}
</code></pre></div></li></ol><h2 id="需要包含的头文件">需要包含的头文件<a class="header-anchor" href="#需要包含的头文件">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>#include &quot;lib/conv/conv3d/conv3d_api.h&quot;
</code></pre></div></article></div>`,1)])])}const m=a(d,[["render",h]]);export{b as __pageData,m as default};
